/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  generateApiTokenPlaintext,
  hashApiToken,
  computeTokenExpiresAt,
  isOmnichannelApiTokenExpired,
} from "../_shared/omnichannelPublicApi/auth.ts";
import {
  parseAllowedOriginsInput,
  validateSdkAllowedOrigins,
} from "../_shared/omnichannelPublicApi/tokenOrigins.ts";
import { isValidWebId, normalizeWebId } from "../_shared/omnichannelPublicApi/urlParams.ts";
import { handleLeadTemplateMappingAction } from "../_shared/omnichannelPublicApi/leadTemplateMappingManage.ts";
import { handleWebIdWhatsAppAccountAction } from "../_shared/omnichannelPublicApi/webIdWhatsAppAccountManage.ts";

const MAX_ACTIVE_TOKENS_PER_ORG = 50;

const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

async function requireOrgAdmin(
  admin: ReturnType<typeof createClient>,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();

  if (profile?.active_organization_id !== organizationId) {
    return json({ success: false, error: "Organisasi tidak aktif.", code: "FORBIDDEN" }, 403);
  }

  const { data: roleRow } = await admin
    .from("user_roles")
    .select("role")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .maybeSingle();

  const role = String(roleRow?.role ?? "").toLowerCase();
  if (!["owner", "admin"].includes(role)) {
    return json({ success: false, error: "Hanya owner/admin.", code: "FORBIDDEN" }, 403);
  }

  return null;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { status: 200, headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceKey) return json({ error: "Server misconfigured" }, 503);

  const admin = createClient(supabaseUrl, serviceKey);

  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return json({ error: "Unauthorized" }, 401);

  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user) return json({ error: "Invalid token" }, 401);

  let body: Record<string, unknown> = {};
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return json({ error: "Invalid JSON" }, 400);
  }

  const organizationId = String(body.organizationId ?? "").trim();
  if (!organizationId) return json({ error: "organizationId wajib." }, 400);

  const adminErr = await requireOrgAdmin(admin, userRes.user.id, organizationId);
  if (adminErr) return adminErr;

  const webIdAccountResponse = await handleWebIdWhatsAppAccountAction(
    admin,
    body,
    organizationId,
    json,
  );
  if (webIdAccountResponse) return webIdAccountResponse;

  const mappingResponse = await handleLeadTemplateMappingAction(admin, body, organizationId, json);
  if (mappingResponse) return mappingResponse;

  const action = String(body.action ?? "").trim();

  if (action === "listTokens") {
    const { data, error } = await admin
      .from("organization_omnichannel_api_tokens")
      .select(
        "id, label, web_id, token_prefix, token_type, allowed_origins, whatsapp_invoice_template_name, whatsapp_lead_template_name, is_active, expires_at, last_used_at, revoked_at, created_at",
      )
      .eq("organization_id", organizationId)
      .order("is_active", { ascending: false })
      .order("created_at", { ascending: false });

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, tokens: data ?? [] });
  }

  if (action === "revokeToken") {
    const tokenId = String(body.tokenId ?? "").trim();
    if (!tokenId) return json({ error: "tokenId wajib." }, 400);

    const { data: existing, error: fetchErr } = await admin
      .from("organization_omnichannel_api_tokens")
      .select("id, is_active, web_id, token_type")
      .eq("id", tokenId)
      .eq("organization_id", organizationId)
      .maybeSingle();

    if (fetchErr) return json({ success: false, error: fetchErr.message }, 500);
    if (!existing) return json({ success: false, error: "Token tidak ditemukan." }, 404);

    if (!existing.is_active) {
      return json({ success: true });
    }

    const revokedWebId = String(existing.web_id ?? "").trim();
    const revokedTokenType = String(existing.token_type ?? "");

    const { error } = await admin
      .from("organization_omnichannel_api_tokens")
      .update({
        is_active: false,
        revoked_at: new Date().toISOString(),
        revoked_by: userRes.user.id,
        updated_at: new Date().toISOString(),
      })
      .eq("id", tokenId)
      .eq("organization_id", organizationId);

    if (error) return json({ success: false, error: error.message }, 500);

    if (revokedTokenType === "sdk" && revokedWebId) {
      const { error: syncErr } = await admin.rpc("sync_analytics_web_access_for_web_id", {
        p_organization_id: organizationId,
        p_web_id: revokedWebId,
        p_created_by: null,
      });
      if (syncErr) {
        return json({
          success: false,
          error: `Token dicabut, tetapi sinkronisasi akses Traffic gagal: ${syncErr.message}`,
        }, 500);
      }
    }

    return json({ success: true });
  }

  if (action === "updateTokenOrigins") {
    const tokenId = String(body.tokenId ?? "").trim();
    if (!tokenId) return json({ success: false, error: "tokenId wajib." }, 400);

    const allowedOrigins = parseAllowedOriginsInput(body.allowed_origins);
    const originsErr = validateSdkAllowedOrigins(allowedOrigins);
    if (originsErr) {
      return json({ success: false, error: originsErr }, 422);
    }

    const { data: existing, error: fetchErr } = await admin
      .from("organization_omnichannel_api_tokens")
      .select("id, token_type, is_active, expires_at")
      .eq("id", tokenId)
      .eq("organization_id", organizationId)
      .maybeSingle();

    if (fetchErr) return json({ success: false, error: fetchErr.message }, 500);
    if (!existing) return json({ success: false, error: "Token tidak ditemukan." }, 404);

    if (!existing.is_active) {
      return json({ success: false, error: "Token sudah dicabut." }, 422);
    }

    if (isOmnichannelApiTokenExpired(existing.expires_at as string | null)) {
      return json({ success: false, error: "Token sudah kedaluwarsa." }, 422);
    }

    if (String(existing.token_type ?? "") !== "sdk") {
      return json({
        success: false,
        error: "Hanya token SDK yang dapat mengubah allowed origins.",
      }, 422);
    }

    const { data: updated, error } = await admin
      .from("organization_omnichannel_api_tokens")
      .update({
        allowed_origins: allowedOrigins,
        updated_at: new Date().toISOString(),
      })
      .eq("id", tokenId)
      .eq("organization_id", organizationId)
      .select("id, web_id, token_prefix, token_type, label, allowed_origins, expires_at, updated_at")
      .single();

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, token: updated });
  }

  if (action === "getSettings") {
    const { data } = await admin
      .from("organization_omnichannel_api_settings")
      .select("*")
      .eq("organization_id", organizationId)
      .maybeSingle();

    return json({
      success: true,
      settings: data ?? {
        organization_id: organizationId,
        default_whatsapp_invoice_template_name: null,
        default_whatsapp_invoice_template_language: null,
        default_whatsapp_lead_template_name: null,
        default_whatsapp_lead_template_language: null,
        offline_conversion_enabled: true,
      },
    });
  }

  if (action === "updateSettings") {
    const { data: existingSettings } = await admin
      .from("organization_omnichannel_api_settings")
      .select(
        "default_whatsapp_invoice_template_name, default_whatsapp_invoice_template_language, default_whatsapp_lead_template_name, default_whatsapp_lead_template_language, offline_conversion_enabled",
      )
      .eq("organization_id", organizationId)
      .maybeSingle();

    const normalizeTemplateLanguage = (value: unknown): string | null => {
      if (value == null) return null;
      const trimmed = String(value).trim();
      return trimmed || null;
    };

    const invoiceTemplateName =
      body.default_whatsapp_invoice_template_name !== undefined
        ? body.default_whatsapp_invoice_template_name != null
          ? String(body.default_whatsapp_invoice_template_name).trim() || null
          : null
        : existingSettings?.default_whatsapp_invoice_template_name ?? null;

    const leadTemplateName =
      body.default_whatsapp_lead_template_name !== undefined
        ? body.default_whatsapp_lead_template_name != null
          ? String(body.default_whatsapp_lead_template_name).trim() || null
          : null
        : existingSettings?.default_whatsapp_lead_template_name ?? null;

    let invoiceTemplateLanguage =
      body.default_whatsapp_invoice_template_language !== undefined
        ? normalizeTemplateLanguage(body.default_whatsapp_invoice_template_language)
        : existingSettings?.default_whatsapp_invoice_template_language ?? null;

    let leadTemplateLanguage =
      body.default_whatsapp_lead_template_language !== undefined
        ? normalizeTemplateLanguage(body.default_whatsapp_lead_template_language)
        : existingSettings?.default_whatsapp_lead_template_language ?? null;

    if (invoiceTemplateName && !invoiceTemplateLanguage) {
      invoiceTemplateLanguage = "id";
    }
    if (leadTemplateName && !leadTemplateLanguage) {
      leadTemplateLanguage = "id";
    }

    const patch = {
      organization_id: organizationId,
      default_whatsapp_invoice_template_name: invoiceTemplateName,
      default_whatsapp_invoice_template_language: invoiceTemplateLanguage,
      default_whatsapp_lead_template_name: leadTemplateName,
      default_whatsapp_lead_template_language: leadTemplateLanguage,
      offline_conversion_enabled:
        body.offline_conversion_enabled !== undefined
          ? body.offline_conversion_enabled !== false
          : existingSettings?.offline_conversion_enabled !== false,
      updated_at: new Date().toISOString(),
    };

    const { error } = await admin.from("organization_omnichannel_api_settings").upsert(patch, {
      onConflict: "organization_id",
    });
    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, settings: patch });
  }

  if (action === "createToken") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    if (!isValidWebId(webId)) {
      return json({
        success: false,
        error: "web_id tidak valid (lowercase, alphanumeric + hyphen, min 3 karakter).",
      }, 422);
    }

    const label = body.label != null ? String(body.label).trim() : null;
    const rawTokenType = String(body.token_type ?? "sdk").trim();
    if (rawTokenType === "legacy_full") {
      return json({
        success: false,
        error: "token_type legacy_full tidak dapat dibuat dari UI.",
      }, 422);
    }
    if (rawTokenType !== "sdk" && rawTokenType !== "server") {
      return json({
        success: false,
        error: "token_type harus sdk atau server.",
      }, 422);
    }
    const tokenType = rawTokenType as "sdk" | "server";

    const allowedOrigins = parseAllowedOriginsInput(body.allowed_origins);

    if (tokenType === "sdk") {
      const originsErr = validateSdkAllowedOrigins(allowedOrigins);
      if (originsErr) {
        return json({ success: false, error: originsErr }, 422);
      }
    }

    let expiresAt: string | null = null;
    if (body.expires_at) {
      const parsed = new Date(String(body.expires_at));
      if (Number.isNaN(parsed.getTime())) {
        return json({ success: false, error: "expires_at tidak valid." }, 422);
      }
      expiresAt = parsed.toISOString();
    } else if (body.expires_in_days != null && body.expires_in_days !== "") {
      const days = Number(body.expires_in_days);
      if (!Number.isFinite(days) || days <= 0) {
        return json({
          success: false,
          error: "expires_in_days harus angka positif (mis. 30, 90, 365).",
        }, 422);
      }
      expiresAt = computeTokenExpiresAt(days);
    }

    const { data: activeRows, error: activeCountErr } = await admin
      .from("organization_omnichannel_api_tokens")
      .select("id, expires_at")
      .eq("organization_id", organizationId)
      .eq("is_active", true);

    if (activeCountErr) {
      return json({ success: false, error: activeCountErr.message }, 500);
    }

    const activeCount = (activeRows ?? []).filter(
      (row) => !isOmnichannelApiTokenExpired(row.expires_at as string | null),
    ).length;

    if (activeCount >= MAX_ACTIVE_TOKENS_PER_ORG) {
      return json({
        success: false,
        error: `Batas token aktif tercapai (maks. ${MAX_ACTIVE_TOKENS_PER_ORG} per organisasi). Cabut token yang tidak dipakai.`,
        code: "LIMIT_EXCEEDED",
      }, 422);
    }

    const plaintext = generateApiTokenPlaintext();
    const tokenHash = await hashApiToken(plaintext);
    const tokenPrefix = plaintext.slice(0, 16);

    const { data: inserted, error } = await admin
      .from("organization_omnichannel_api_tokens")
      .insert({
        organization_id: organizationId,
        token_hash: tokenHash,
        token_prefix: tokenPrefix,
        label,
        web_id: webId,
        allowed_origins: allowedOrigins,
        token_type: tokenType,
        whatsapp_invoice_template_name:
          body.whatsapp_invoice_template_name != null
            ? String(body.whatsapp_invoice_template_name).trim() || null
            : null,
        whatsapp_lead_template_name:
          body.whatsapp_lead_template_name != null
            ? String(body.whatsapp_lead_template_name).trim() || null
            : null,
        expires_at: expiresAt,
        created_by: userRes.user.id,
      })
      .select("id, web_id, token_prefix, token_type, label, allowed_origins, expires_at, created_at")
      .single();

    if (error) return json({ success: false, error: error.message }, 500);

    if (tokenType === "sdk") {
      const { error: syncErr } = await admin.rpc("sync_analytics_web_access_for_web_id", {
        p_organization_id: organizationId,
        p_web_id: webId,
        p_created_by: userRes.user.id,
      });
      if (syncErr) {
        return json({
          success: false,
          error: `Token dibuat, tetapi aktivasi akses Traffic gagal: ${syncErr.message}`,
        }, 500);
      }
    }

    return json({
      success: true,
      token: inserted,
      plaintext_token: plaintext,
      message: "Simpan token ini — hanya ditampilkan sekali.",
    });
  }

  return json({ error: "Unknown action" }, 400);
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { apiError } from "./response.ts";
import { buildCorsHeaders } from "./response.ts";

export type OmnichannelApiTokenType = "sdk" | "server" | "legacy_full";

export type OmnichannelApiTokenContext = {
  tokenId: string;
  organizationId: string;
  webId: string;
  allowedOrigins: string[];
  whatsappInvoiceTemplateName: string | null;
  whatsappLeadTemplateName: string | null;
  tokenType: OmnichannelApiTokenType;
};

const SDK_PATHS = new Set([
  "/api/v1/traffic-logs",
  "/api/v1/page-views/heartbeat",
  "/api/v1/click-events",
  "/api/v1/wa-link-clicks",
  "/api/v1/leads",
]);

const SERVER_PATHS = new Set(["/api/v1/orders/invoice-trigger"]);

const BROWSER_SEC_FETCH_SITES = new Set(["same-origin", "same-site", "cross-site"]);

/** Opsi A — invoice-trigger tidak boleh dipanggil dari browser (Origin / Sec-Fetch-Site). */
export function assertInvoiceNotFromBrowser(
  req: Request,
  corsHeaders: Record<string, string>,
): Response | null {
  const origin = req.headers.get("Origin")?.trim();
  if (origin) {
    return apiError(
      "invoice-trigger tidak boleh dipanggil dari browser. Gunakan token Server di backend (Edge Function / server).",
      "BROWSER_REQUEST_REJECTED",
      403,
      corsHeaders,
    );
  }

  const secFetchSite = req.headers.get("Sec-Fetch-Site")?.trim().toLowerCase();
  if (secFetchSite && BROWSER_SEC_FETCH_SITES.has(secFetchSite)) {
    return apiError(
      "invoice-trigger tidak boleh dipanggil dari browser. Gunakan token Server di backend (Edge Function / server).",
      "BROWSER_REQUEST_REJECTED",
      403,
      corsHeaders,
    );
  }

  return null;
}

export function assertPathAllowedForTokenType(
  path: string,
  tokenType: OmnichannelApiTokenType,
  corsHeaders: Record<string, string>,
): Response | null {
  if (tokenType === "legacy_full") return null;

  if (tokenType === "sdk") {
    if (SDK_PATHS.has(path)) return null;
    if (path === "/api/v1/orders/invoice-trigger") {
      return apiError(
        "Token tipe SDK tidak boleh memanggil invoice-trigger. Gunakan token Server di backend.",
        "FORBIDDEN",
        403,
        corsHeaders,
      );
    }
    return apiError(
      "Token tipe SDK tidak diizinkan untuk endpoint ini.",
      "FORBIDDEN",
      403,
      corsHeaders,
    );
  }

  if (tokenType === "server") {
    if (SERVER_PATHS.has(path)) return null;
    return apiError(
      "Token tipe Server hanya untuk invoice-trigger.",
      "FORBIDDEN",
      403,
      corsHeaders,
    );
  }

  return null;
}

function normalizeTokenType(value: unknown): OmnichannelApiTokenType {
  const t = String(value ?? "legacy_full").trim();
  if (t === "sdk" || t === "server" || t === "legacy_full") return t;
  return "legacy_full";
}

const RATE_LIMIT_PER_MINUTE = 100;
const MS_PER_DAY = 86_400_000;

/** True when expires_at is in the past (UTC). Null/empty = never expires. */
export function isOmnichannelApiTokenExpired(expiresAt: string | null | undefined): boolean {
  if (!expiresAt) return false;
  const ts = new Date(expiresAt).getTime();
  return Number.isFinite(ts) && ts < Date.now();
}

export function computeTokenExpiresAt(expiresInDays: number): string | null {
  if (!Number.isFinite(expiresInDays) || expiresInDays <= 0) return null;
  return new Date(Date.now() + expiresInDays * MS_PER_DAY).toISOString();
}

async function sha256Hex(input: string): Promise<string> {
  const data = new TextEncoder().encode(input);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

export async function hashApiToken(plaintext: string): Promise<string> {
  return sha256Hex(plaintext);
}

export function generateApiTokenPlaintext(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  const random = Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
  return `sk_omni_${random}`;
}

export function extractBearerToken(authHeader: string | null): string {
  if (!authHeader?.startsWith("Bearer ")) return "";
  return authHeader.slice("Bearer ".length).trim();
}

export async function authenticateOmnichannelApiToken(
  admin: SupabaseClient,
  req: Request,
): Promise<{ ctx: OmnichannelApiTokenContext; corsHeaders: Record<string, string> } | { error: Response }> {
  const origin = req.headers.get("Origin");
  const bearer = extractBearerToken(req.headers.get("Authorization"));

  if (!bearer || !bearer.startsWith("sk_omni_")) {
    const cors = buildCorsHeaders(origin, []);
    return {
      error: apiError("Token API tidak valid atau tidak ada.", "UNAUTHORIZED", 401, cors),
    };
  }

  const tokenHash = await hashApiToken(bearer);

  const { data: row, error } = await admin
    .from("organization_omnichannel_api_tokens")
    .select(
      "id, organization_id, web_id, allowed_origins, whatsapp_invoice_template_name, whatsapp_lead_template_name, is_active, expires_at, token_type",
    )
    .eq("token_hash", tokenHash)
    .maybeSingle();

  const allowedOrigins = Array.isArray(row?.allowed_origins)
    ? (row!.allowed_origins as string[])
    : [];
  const corsHeaders = buildCorsHeaders(origin, allowedOrigins);

  if (error || !row) {
    return {
      error: apiError("Token API tidak dikenali.", "UNAUTHORIZED", 401, corsHeaders),
    };
  }

  if (!row.is_active) {
    return {
      error: apiError("Token API telah dicabut.", "FORBIDDEN", 403, corsHeaders),
    };
  }

  if (isOmnichannelApiTokenExpired(row.expires_at)) {
    return {
      error: apiError("Token API sudah kedaluwarsa.", "FORBIDDEN", 403, corsHeaders),
    };
  }

  const rateErr = await checkRateLimit(admin, row.id, corsHeaders);
  if (rateErr) return { error: rateErr };

  void admin
    .from("organization_omnichannel_api_tokens")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", row.id);

  return {
    ctx: {
      tokenId: row.id,
      organizationId: row.organization_id,
      webId: row.web_id,
      allowedOrigins,
      whatsappInvoiceTemplateName: row.whatsapp_invoice_template_name ?? null,
      whatsappLeadTemplateName: row.whatsapp_lead_template_name ?? null,
      tokenType: normalizeTokenType(row.token_type),
    },
    corsHeaders,
  };
}

async function checkRateLimit(
  admin: SupabaseClient,
  tokenId: string,
  corsHeaders: Record<string, string>,
): Promise<Response | null> {
  const now = new Date();
  const windowStart = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours(), now.getUTCMinutes()),
  ).toISOString();

  const { data: existing } = await admin
    .from("organization_omnichannel_api_rate_limits")
    .select("request_count")
    .eq("token_id", tokenId)
    .eq("window_start", windowStart)
    .maybeSingle();

  const count = (existing?.request_count as number | undefined) ?? 0;
  if (count >= RATE_LIMIT_PER_MINUTE) {
    return apiError(
      "Batas permintaan terlampaui (100/menit). Coba lagi nanti.",
      "RATE_LIMITED",
      429,
      corsHeaders,
    );
  }

  await admin.from("organization_omnichannel_api_rate_limits").upsert(
    {
      token_id: tokenId,
      window_start: windowStart,
      request_count: count + 1,
    },
    { onConflict: "token_id,window_start" },
  );

  return null;
}

export function isUuid(v: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
}

/** Respons JSON standar API publik Omnichannel (Bahasa Indonesia di pesan error). */

export type ApiErrorCode =
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "BROWSER_REQUEST_REJECTED"
  | "VALIDATION_ERROR"
  | "NOT_FOUND"
  | "CONFLICT"
  | "RATE_LIMITED"
  | "LEAD_NOT_MATCHED"
  | "SESSION_NOT_READY"
  | "INTERNAL_ERROR";

export function apiJson(
  body: Record<string, unknown>,
  status: number,
  corsHeaders: Record<string, string>,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

export function apiSuccess(
  data: Record<string, unknown>,
  status: number,
  corsHeaders: Record<string, string>,
): Response {
  return apiJson({ success: true, ...data }, status, corsHeaders);
}

export function apiError(
  error: string,
  code: ApiErrorCode,
  status: number,
  corsHeaders: Record<string, string>,
  details?: unknown,
): Response {
  return apiJson(
    {
      success: false,
      error,
      code,
      ...(details !== undefined ? { details } : {}),
    },
    status,
    corsHeaders,
  );
}

export function buildCorsHeaders(origin: string | null, allowedOrigins: string[]): Record<string, string> {
  const base = {
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Max-Age": "86400",
  };

  if (!origin) {
    return { ...base, "Access-Control-Allow-Origin": "*" };
  }

  const normalized = origin.trim().toLowerCase();
  const allowed = allowedOrigins.map((o) => o.trim().toLowerCase()).filter(Boolean);

  if (allowed.length === 0) {
    return { ...base, "Access-Control-Allow-Origin": "*" };
  }

  if (allowed.includes(normalized) || allowed.includes("*")) {
    return { ...base, "Access-Control-Allow-Origin": origin };
  }

  return { ...base, "Access-Control-Allow-Origin": "null" };
}

const ORIGIN_PATTERN = /^https?:\/\/.+/i;

export function parseAllowedOriginsInput(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  return (raw as unknown[])
    .map((o) => String(o).trim())
    .filter((o) => o.length > 0);
}

function isValidOriginUrl(origin: string): boolean {
  return ORIGIN_PATTERN.test(origin);
}

/** Returns error message or null if valid. */
export function validateSdkAllowedOrigins(origins: string[]): string | null {
  if (origins.length === 0) {
    return "allowed_origins wajib diisi untuk token tipe SDK.";
  }

  for (const origin of origins) {
    if (!isValidOriginUrl(origin)) {
      return `Origin tidak valid: "${origin}". Gunakan format http:// atau https:// (mis. https://toko-anda.com).`;
    }
  }

  return null;
}

/** Ekstraksi UTM dan click ID dari URL landing page. */

export type ParsedUrlParams = {
  utm_source: string | null;
  utm_medium: string | null;
  utm_campaign: string | null;
  utm_term: string | null;
  utm_content: string | null;
  gclid: string | null;
  fbclid: string | null;
  msclkid: string | null;
  gbraid: string | null;
  wbraid: string | null;
  path: string;
};

function pickParam(searchParams: URLSearchParams, key: string): string | null {
  const v = searchParams.get(key);
  return v && v.trim() ? v.trim() : null;
}

export function parsePageUrl(raw: string): ParsedUrlParams | null {
  try {
    const url = new URL(raw);
    const sp = url.searchParams;
    return {
      utm_source: pickParam(sp, "utm_source"),
      utm_medium: pickParam(sp, "utm_medium"),
      utm_campaign: pickParam(sp, "utm_campaign"),
      utm_term: pickParam(sp, "utm_term"),
      utm_content: pickParam(sp, "utm_content"),
      gclid: pickParam(sp, "gclid"),
      fbclid: pickParam(sp, "fbclid"),
      msclkid: pickParam(sp, "msclkid"),
      gbraid: pickParam(sp, "gbraid"),
      wbraid: pickParam(sp, "wbraid"),
      path: url.pathname || "/",
    };
  } catch {
    return null;
  }
}

export function coalesceUtm(
  body: Record<string, unknown>,
  parsed: ParsedUrlParams | null,
): ParsedUrlParams {
  return {
    utm_source: strOr(body.utm_source) ?? parsed?.utm_source ?? null,
    utm_medium: strOr(body.utm_medium) ?? parsed?.utm_medium ?? null,
    utm_campaign: strOr(body.utm_campaign) ?? parsed?.utm_campaign ?? null,
    utm_term: strOr(body.utm_term) ?? parsed?.utm_term ?? null,
    utm_content: strOr(body.utm_content) ?? parsed?.utm_content ?? null,
    gclid: strOr(body.gclid) ?? parsed?.gclid ?? null,
    fbclid: strOr(body.fbclid) ?? parsed?.fbclid ?? null,
    msclkid: strOr(body.msclkid) ?? parsed?.msclkid ?? null,
    gbraid: strOr(body.gbraid) ?? parsed?.gbraid ?? null,
    wbraid: strOr(body.wbraid) ?? parsed?.wbraid ?? null,
    path: parsed?.path ?? "/",
  };
}

function strOr(v: unknown): string | null {
  if (v == null) return null;
  const s = String(v).trim();
  return s || null;
}

