const MAPPER_SUBMISSION_LOOKBACK_DAYS = 30;
const MAPPER_SUBMISSION_FETCH_LIMIT = 30;

async function fetchMapperFormSubmissions(
  admin: SupabaseClient,
  organizationId: string,
  webId: string,
) {
  const since = new Date();
  since.setDate(since.getDate() - MAPPER_SUBMISSION_LOOKBACK_DAYS);

  const { data, error } = await admin
    .from("lead_submissions")
    .select("id, name, email, phone_number, notes, form_data, form_id, status, submitted_at")
    .eq("organization_id", organizationId)
    .eq("web_id", webId)
    .eq("status", "submitted")
    .gte("submitted_at", since.toISOString())
    .order("submitted_at", { ascending: false })
    .limit(MAPPER_SUBMISSION_FETCH_LIMIT);

  if (error) throw error;

  return (data ?? []).filter((row) => isMapperRelevantSubmission(row));
}

export async function handleLeadTemplateMappingAction(
  admin: SupabaseClient,
  body: Record<string, unknown>,
  organizationId: string,
  json: ManageJson,
): Promise<Response | null> {
  const action = String(body.action ?? "").trim();

  if (action === "listLeadMappingWebIds") {
    const { data, error } = await admin
      .from("organization_omnichannel_api_tokens")
      .select("web_id, is_active, expires_at")
      .eq("organization_id", organizationId);

    if (error) return json({ success: false, error: error.message }, 500);

    const webIds = new Set<string>();
    for (const row of data ?? []) {
      if (!row.is_active) continue;
      if (isOmnichannelApiTokenExpired(row.expires_at as string | null)) continue;
      const wid = normalizeWebId(String(row.web_id ?? ""));
      if (wid) webIds.add(wid);
    }

    return json({ success: true, web_ids: [...webIds].sort() });
  }

  if (action === "getLeadTemplateMapping") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    const templateName = String(body.template_name ?? "").trim();
    const templateLanguage = normalizeTemplateLanguage(body.template_language);

    if (!webId || !templateName) {
      return json({ success: false, error: "web_id dan template_name wajib." }, 400);
    }

    const { data, error } = await admin
      .from("organization_whatsapp_templates")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("web_id", webId)
      .eq("purpose", "lead")
      .eq("template_name", templateName)
      .eq("template_language", templateLanguage)
      .maybeSingle();

    if (error) return json({ success: false, error: error.message }, 500);

    return json({
      success: true,
      mapping: data ?? null,
    });
  }

  if (action === "getRecentLeadFormDataKeys") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    if (!webId) return json({ success: false, error: "web_id wajib." }, 400);

    try {
      const rows = await fetchMapperFormSubmissions(admin, organizationId, webId);
      const keys = aggregateMapperFormDataKeys(rows);
      return json({ success: true, keys });
    } catch (err) {
      const message = err instanceof Error ? err.message : "Gagal memuat field form.";
      return json({ success: false, error: message }, 500);
    }
  }

  if (action === "getLatestLeadSubmissionForPreview") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    if (!webId) return json({ success: false, error: "web_id wajib." }, 400);

    try {
      const rows = await fetchMapperFormSubmissions(admin, organizationId, webId);
      const submission = rows[0] ?? null;
      return json({
        success: true,
        submission: submission
          ? {
            id: submission.id,
            name: submission.name,
            email: submission.email,
            phone_number: submission.phone_number,
            notes: submission.notes,
            form_data: submission.form_data,
            submitted_at: submission.submitted_at,
          }
          : null,
        form_data_keys: aggregateMapperFormDataKeys(rows),
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : "Gagal memuat submission.";
      return json({ success: false, error: message }, 500);
    }
  }

  if (action === "upsertLeadTemplateMapping") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    const templateName = String(body.template_name ?? "").trim();
    const templateLanguage = normalizeTemplateLanguage(body.template_language);
    const parameterMapping = body.parameter_mapping as Record<string, string> | null;

    if (!webId || !templateName) {
      return json({ success: false, error: "web_id dan template_name wajib." }, 400);
    }
    if (!parameterMapping || typeof parameterMapping !== "object") {
      return json({ success: false, error: "parameter_mapping wajib (objek slot → field)." }, 400);
    }

    const slots = await fetchTemplateBodySlotCount(
      admin,
      organizationId,
      templateName,
      templateLanguage,
      webId,
    );
    if (!slots.ok) return json({ success: false, error: slots.error }, 422);

    const validationError = validateParameterMappingForSlots(parameterMapping, slots.slotCount);
    if (validationError) {
      return json({ success: false, error: validationError }, 422);
    }

    const now = new Date().toISOString();
    const patch = {
      organization_id: organizationId,
      web_id: webId,
      purpose: "lead",
      template_name: templateName,
      template_language: templateLanguage,
      parameter_mapping: parameterMapping,
      is_active: true,
      updated_at: now,
    };

    const { data, error } = await admin
      .from("organization_whatsapp_templates")
      .upsert(patch, {
        onConflict: "organization_id,web_id,purpose,template_name,template_language",
      })
      .select("*")
      .single();

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, mapping: data, slot_count: slots.slotCount });
  }

  if (action === "previewLeadTemplateMapping") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    const templateName = String(body.template_name ?? "").trim();
    const templateLanguage = normalizeTemplateLanguage(body.template_language);
    const parameterMapping = body.parameter_mapping as Record<string, string> | null;
    const submissionId = body.lead_submission_id != null
      ? String(body.lead_submission_id).trim()
      : null;

    if (!webId || !templateName) {
      return json({ success: false, error: "web_id dan template_name wajib." }, 400);
    }
    if (!parameterMapping || typeof parameterMapping !== "object") {
      return json({ success: false, error: "parameter_mapping wajib." }, 400);
    }

    const bodyKeys = parseParameterMapping(parameterMapping);
    if (!bodyKeys) {
      return json({ success: false, error: "parameter_mapping tidak valid." }, 422);
    }

    const { data: submissionRows, error: subErr } = submissionId
      ? await admin
        .from("lead_submissions")
        .select("id, name, email, phone_number, notes, form_data, submitted_at")
        .eq("organization_id", organizationId)
        .eq("id", submissionId)
        .limit(1)
      : await admin
        .from("lead_submissions")
        .select("id, name, email, phone_number, notes, form_data, submitted_at")
        .eq("organization_id", organizationId)
        .eq("web_id", webId)
        .order("submitted_at", { ascending: false })
        .limit(1);

    if (subErr) return json({ success: false, error: subErr.message }, 500);

    const submission = (submissionRows ?? [])[0] ?? null;

    const sample = submission ?? {
      name: "Budi Santoso",
      email: "budi@example.com",
      phone_number: "6281234567890",
      notes: null,
      form_data: {
        package_label: "Paket Gold",
        event_date: "2026-12-01",
        event_time: "10:00",
        event_address: "Jakarta",
      },
    };

    const formData = (sample.form_data ?? null) as Record<string, unknown> | null;
    const leadArgs = {
      name: String(sample.name ?? ""),
      email: sample.email != null ? String(sample.email) : null,
      phoneNumber: String(sample.phone_number ?? ""),
      notes: sample.notes != null ? String(sample.notes) : null,
      formData,
    };
    const bodyParams = buildPreviewParamsFromMapping(bodyKeys, leadArgs);

    let previewText = bodyParams.filter((p) => p !== "-").join(" · ");
    const creds = await resolveOrganizationWhatsAppCredentials(admin, organizationId, { webId });
    if (creds.ok && templateName) {
      const wabaId = await resolveWabaId(admin, organizationId, creds.credentials);
      if (wabaId) {
        const components = await fetchMetaTemplateComponents(
          wabaId,
          creds.credentials.accessToken,
          templateName,
          templateLanguage,
        );
        if (components) {
          previewText = renderFilledBodyTemplateText(components, bodyParams);
        }
      }
    }

    const usedSampleFallback = Boolean(
      submission &&
        bodyKeys.some((key) => resolveBodyKeyValue(key, leadArgs) === "-"),
    );

    return json({
      success: true,
      body_params: bodyParams,
      preview_text: previewText,
      submission: submission
        ? {
          id: submission.id,
          submitted_at: submission.submitted_at,
        }
        : null,
      used_sample: !submission || usedSampleFallback,
    });
  }

  if (action === "suggestLeadTemplateMapping") {
    const webId = normalizeWebId(String(body.web_id ?? ""));
    const templateName = String(body.template_name ?? "").trim();
    const templateLanguage = normalizeTemplateLanguage(body.template_language);

    if (!webId || !templateName) {
      return json({ success: false, error: "web_id dan template_name wajib." }, 400);
    }

    const slots = await fetchTemplateBodySlotCount(
      admin,
      organizationId,
      templateName,
      templateLanguage,
      webId,
    );
    if (!slots.ok) return json({ success: false, error: slots.error }, 422);

    const rows = await fetchMapperFormSubmissions(admin, organizationId, webId);
    const recentKeys = aggregateMapperFormDataKeys(rows);

    const parameter_mapping = suggestLeadParameterMapping(
      slots.slotCount,
      recentKeys,
    );

    return json({
      success: true,
      parameter_mapping,
      slot_count: slots.slotCount,
    });
  }

  return null;
}

/** Keys from form_data that have a non-empty value (matches website fields actually submitted). */
export function extractNonEmptyFormDataKeys(formData: unknown): string[] {
  if (!formData || typeof formData !== "object" || Array.isArray(formData)) return [];

  const out: string[] = [];
  for (const [key, value] of Object.entries(formData as Record<string, unknown>)) {
    const k = key.trim();
    if (!k) continue;
    if (value == null) continue;
    if (typeof value === "string" && value.trim() === "") continue;
    out.push(k);
  }

  return out.sort((a, b) => a.localeCompare(b));
}

export function isFloatingWhatsAppStubFormData(formData: unknown): boolean {
  if (!formData || typeof formData !== "object" || Array.isArray(formData)) return false;
  return (formData as Record<string, unknown>).source === "floating_whatsapp";
}

export type MapperFormSubmissionRow = {
  status?: string | null;
  form_id?: string | null;
  form_data?: unknown;
};

/** Website form submissions usable for template field mapping (skip WA floating-click drafts). */
export function isMapperRelevantSubmission(row: MapperFormSubmissionRow): boolean {
  if (isFloatingWhatsAppStubFormData(row.form_data)) return false;
  if (String(row.status ?? "").toLowerCase() === "draft") return false;
  return true;
}

export function aggregateMapperFormDataKeys(
  rows: Array<{ form_data?: unknown }>,
): string[] {
  const keys = new Set<string>();
  for (const row of rows) {
    for (const key of extractNonEmptyFormDataKeys(row.form_data)) {
      keys.add(key);
    }
  }
  return [...keys].sort((a, b) => a.localeCompare(b));
}

import { RESERVED_LEAD_BODY_KEYS } from "./leadFormData.ts";

export type LeadMappingSource =
  | "parameter_mapping"
  | "organization_whatsapp_templates"
  | "fixed_7";

const FORM_DATA_KEY_PATTERN = /^[a-zA-Z][a-zA-Z0-9_]{0,63}$/;

const CORE_MAPPABLE_KEYS = new Set(["name", "email", "phone_number", "notes"]);

const FIXED_7_KEYS = [
  "name",
  "email",
  "phone_number",
  "package_label",
  "event_date",
  "event_time",
  "event_address",
] as const;

export function sanitizeMetaTemplateParam(value: string): string {
  return value
    .replace(/\r\n/g, "\n")
    .replace(/[\n\r]+/g, " · ")
    .replace(/\t/g, " ")
    .replace(/ {5,}/g, "    ")
    .trim()
    .slice(0, 1024);
}

export function paramOrDash(value: unknown): string {
  const s = value == null ? "" : String(value).trim();
  if (s.length === 0) return "-";
  return sanitizeMetaTemplateParam(s);
}

export function isValidLeadMappableFieldKey(key: string): boolean {
  const trimmed = key.trim();
  if (!trimmed) return false;
  if (CORE_MAPPABLE_KEYS.has(trimmed)) return true;
  if (RESERVED_LEAD_BODY_KEYS.has(trimmed)) return false;
  return FORM_DATA_KEY_PATTERN.test(trimmed);
}

/** Parse jsonb parameter_mapping → ordered body keys (slot 1..n). */
export function parseParameterMapping(
  raw: unknown,
  slotCount?: number,
): string[] | null {
  if (raw == null || typeof raw !== "object" || Array.isArray(raw)) return null;
  const obj = raw as Record<string, unknown>;
  const entries = Object.entries(obj)
    .map(([slot, field]) => ({
      slot: Number.parseInt(slot, 10),
      field: String(field ?? "").trim(),
    }))
    .filter((e) => Number.isFinite(e.slot) && e.slot >= 1 && e.field.length > 0)
    .sort((a, b) => a.slot - b.slot);

  if (entries.length === 0) return null;

  const maxSlot = entries[entries.length - 1]!.slot;
  const expected = slotCount ?? maxSlot;
  if (entries.length !== expected) return null;

  for (let i = 1; i <= expected; i++) {
    const found = entries.find((e) => e.slot === i);
    if (!found) return null;
    if (!isValidLeadMappableFieldKey(found.field)) return null;
  }

  return entries.map((e) => e.field);
}

/** Build Record<number, string> from string[] keys for UI. */
export function bodyKeysToParameterMapping(bodyKeys: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  bodyKeys.forEach((key, idx) => {
    out[String(idx + 1)] = key;
  });
  return out;
}

export function resolveBodyKeyValue(
  key: string,
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    notes?: string | null;
    formData: Record<string, unknown> | null;
  },
): string {
  const fd = args.formData ?? {};
  const normalized = key.trim().toLowerCase();

  switch (normalized) {
    case "name":
    case "client":
    case "customer_name":
      return paramOrDash(args.name);
    case "email":
      return paramOrDash(args.email);
    case "phone":
    case "phone_number":
    case "customer_phone":
      return paramOrDash(args.phoneNumber);
    case "notes":
      return paramOrDash(args.notes);
    case "package_label":
    case "package":
    case "needs":
    case "ringkasan_kebutuhan":
      return paramOrDash(fd.package_label ?? fd[normalized] ?? fd[key]);
    case "event_date":
      return paramOrDash(fd.event_date);
    case "event_time":
      return paramOrDash(fd.event_time);
    case "event_address":
    case "office_address":
    case "address":
      return paramOrDash(fd.event_address ?? fd.office_address ?? fd.address);
    case "industry":
    case "business_type":
      return paramOrDash(fd[normalized] ?? fd[key]);
    default:
      return paramOrDash(fd[normalized] ?? fd[key]);
  }
}

export function buildParamsFromMapping(
  bodyKeys: string[],
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    notes?: string | null;
    formData: Record<string, unknown> | null;
  },
): string[] {
  return bodyKeys.map((key) => resolveBodyKeyValue(key, args));
}

const PREVIEW_SAMPLE_SUBMISSION = {
  name: "Budi Santoso",
  email: "budi@example.com",
  phoneNumber: "6281234567890",
  notes: null as string | null,
  formData: {
    package_label: "Paket Gold",
    event_date: "2026-12-01",
    event_time: "10:00",
    event_address: "Jakarta",
  } as Record<string, unknown>,
};

/** Preview: use submission values, fall back to sample when a mapped field is empty. */
export function buildPreviewParamsFromMapping(
  bodyKeys: string[],
  args: {
    name: string;
    email: string | null;
    phoneNumber: string;
    notes?: string | null;
    formData: Record<string, unknown> | null;
  },
): string[] {
  const sample = PREVIEW_SAMPLE_SUBMISSION;
  return bodyKeys.map((key) => {
    const real = resolveBodyKeyValue(key, args);
    if (real !== "-") return real;
    return resolveBodyKeyValue(key, {
      name: sample.name,
      email: sample.email,
      phoneNumber: sample.phoneNumber,
      notes: sample.notes,
      formData: sample.formData,
    });
  });
}

export function suggestLeadParameterMapping(
  slotCount: number,
  recentFormDataKeys: string[] = [],
): Record<string, string> {
  if (slotCount <= 0) return {};

  const recentSet = new Set(
    recentFormDataKeys.map((k) => k.trim()).filter((k) => k.length > 0),
  );
  const suggested: string[] = [];

  for (const key of ["name", "email", "phone_number"]) {
    if (suggested.length >= slotCount) break;
    suggested.push(key);
  }

  const preferredFormData = [
    "package_label",
    "event_date",
    "event_time",
    "event_address",
    "industry",
    "consent",
  ] as const;

  for (const key of preferredFormData) {
    if (suggested.length >= slotCount) break;
    if (recentSet.has(key) && !suggested.includes(key)) {
      suggested.push(key);
    }
  }

  const extras = recentFormDataKeys
    .map((k) => k.trim())
    .filter((k) => isValidLeadMappableFieldKey(k) && !CORE_MAPPABLE_KEYS.has(k));

  for (const key of extras) {
    if (suggested.length >= slotCount) break;
    if (!suggested.includes(key)) suggested.push(key);
  }

  while (suggested.length < slotCount) {
    suggested.push(`field_${suggested.length + 1}`);
  }

  return bodyKeysToParameterMapping(suggested.slice(0, slotCount));
}

function countPlaceholders(text: string): number {
  return (text.match(/\{\{[^}]+\}\}/g) ?? []).length;
}

/** Body-only variable count from Meta template components. */
export function countTemplateBodySlotsFromComponents(
  components: unknown[] | null | undefined,
): number {
  if (!Array.isArray(components)) return 0;
  let total = 0;
  for (const raw of components) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    if (String(c.type ?? "").toUpperCase() !== "BODY") continue;
    total += countPlaceholders(String(c.text ?? ""));
  }
  return total;
}

export function validateParameterMappingForSlots(
  parameterMapping: Record<string, string>,
  slotCount: number,
): string | null {
  if (slotCount <= 0) return "Template tidak memiliki variabel body.";
  const keys = parseParameterMapping(parameterMapping, slotCount);
  if (!keys) {
    return `Mapping harus mengisi slot 1 sampai ${slotCount} dengan field yang valid.`;
  }
  return null;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { countTemplateBodySlotsFromComponents } from "./leadTemplateMapping.ts";
import { fetchMetaTemplateComponents } from "./leadWhatsAppTemplatePreview.ts";
import { resolveOrganizationWhatsAppCredentials } from "./resolveOrganizationWhatsAppCredentials.ts";

const META_API_BASE = "https://graph.facebook.com/v21.0";

export async function resolveWabaIdForOrg(
  admin: SupabaseClient,
  organizationId: string,
  credentials: { whatsappAccountId: string; phoneNumberId: string; accessToken: string },
): Promise<string | null> {
  const { data: acc } = await admin
    .from("organization_whatsapp_accounts")
    .select("whatsapp_business_account_id")
    .eq("id", credentials.whatsappAccountId)
    .eq("organization_id", organizationId)
    .maybeSingle();

  let wabaId = String(acc?.whatsapp_business_account_id ?? "").trim();
  if (!wabaId) {
    const { data: meta } = await admin
      .from("organization_meta_config")
      .select("whatsapp_business_account_id")
      .eq("organization_id", organizationId)
      .maybeSingle();
    wabaId = String(meta?.whatsapp_business_account_id ?? "").trim();
  }

  if (!wabaId && credentials.phoneNumberId) {
    const fields = encodeURIComponent("whatsapp_business_account{id}");
    const url =
      `${META_API_BASE}/${encodeURIComponent(credentials.phoneNumberId)}?fields=${fields}`;
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${credentials.accessToken}` },
    });
    const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    const wabaObj = json.whatsapp_business_account as { id?: string } | undefined;
    wabaId = wabaObj?.id != null ? String(wabaObj.id).trim() : "";
  }

  return wabaId || null;
}

export async function fetchLeadTemplateBodySlotCount(
  admin: SupabaseClient,
  organizationId: string,
  templateName: string,
  templateLanguage: string,
  webId?: string | null,
): Promise<{ ok: true; slotCount: number } | { ok: false; error: string }> {
  const creds = await resolveOrganizationWhatsAppCredentials(admin, organizationId, { webId });
  if (!creds.ok) return { ok: false, error: creds.error };

  const wabaId = await resolveWabaIdForOrg(admin, organizationId, creds.credentials);
  if (!wabaId) {
    return { ok: false, error: "WhatsApp Business Account ID tidak ditemukan." };
  }

  const components = await fetchMetaTemplateComponents(
    wabaId,
    creds.credentials.accessToken,
    templateName,
    templateLanguage,
  );

  if (!components) {
    return { ok: false, error: "Template Meta tidak ditemukan atau belum APPROVED." };
  }

  const slotCount = countTemplateBodySlotsFromComponents(components);
  return { ok: true, slotCount };
}

