}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const META_API_BASE = "https://graph.facebook.com/v21.0";
const MEDIA_HEADER_FORMATS = new Set(["IMAGE", "VIDEO", "DOCUMENT"]);
const EMPTY_PARAM = "-";

function countPlaceholders(text: string): number {
  return (text.match(/\{\{[^}]+\}\}/g) ?? []).length;
}

function normalizeParamValue(raw: unknown): string {
  const s = String(raw ?? "").trim();
  return s.length > 0 ? s.slice(0, 1024) : EMPTY_PARAM;
}

/** Filled template text for livechat storage (no `[Template: name]` prefix — UI already shows badge). */
export function renderFilledTemplateBody(
  templateComponents: unknown[] | null | undefined,
  parameterValues: string[],
): string {
  const params = parameterValues.map((x) => normalizeParamValue(x));
  let idx = 0;
  const parts: string[] = [];
  if (!Array.isArray(templateComponents)) {
    const fallback = params.filter((p) => p !== EMPTY_PARAM).join(" · ");
    return fallback.slice(0, 4090);
  }

  for (const raw of templateComponents) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    const type = String(c.type ?? "").toUpperCase();
    if (type === "HEADER") {
      const fmt = String(c.format ?? "TEXT").toUpperCase();
      if (MEDIA_HEADER_FORMATS.has(fmt)) {
        const n = countPlaceholders(String(c.text ?? ""));
        for (let i = 0; i < n; i++) idx++;
        continue;
      }
      let text = String(c.text ?? "");
      const n = countPlaceholders(text);
      for (let i = 0; i < n; i++) {
        text = text.replace(/\{\{[^}]+\}\}/, params[idx++] ?? EMPTY_PARAM);
      }
      if (text.trim()) parts.push(text.trim());
    } else if (type === "BODY") {
      let text = String(c.text ?? "");
      const n = countPlaceholders(text);
      for (let i = 0; i < n; i++) {
        text = text.replace(/\{\{[^}]+\}\}/, params[idx++] ?? EMPTY_PARAM);
      }
      if (text.trim()) parts.push(text.trim());
    } else if (type === "BUTTONS") {
      const buttons = c.buttons;
      if (!Array.isArray(buttons)) continue;
      for (const btn of buttons) {
        if (!btn || typeof btn !== "object") continue;
        const b = btn as Record<string, unknown>;
        if (String(b.type ?? "").toUpperCase() !== "URL") continue;
        const n = countPlaceholders(String(b.url ?? ""));
        for (let i = 0; i < n; i++) idx++;
      }
    }
  }

  if (parts.length === 0) {
    const fallback = params.filter((p) => p !== EMPTY_PARAM).join(" · ");
    return fallback.slice(0, 4090);
  }
  return parts.join("\n\n").slice(0, 4090);
}

/** Fill BODY placeholders only — matches WhatsApp API body `parameters` (not header). */
export function renderFilledBodyTemplateText(
  templateComponents: unknown[] | null | undefined,
  bodyParams: string[],
): string {
  const params = bodyParams.map((x) => normalizeParamValue(x));
  if (!Array.isArray(templateComponents)) {
    const fallback = params.filter((p) => p !== EMPTY_PARAM).join(" · ");
    return fallback.slice(0, 4090);
  }

  for (const raw of templateComponents) {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) continue;
    const c = raw as Record<string, unknown>;
    if (String(c.type ?? "").toUpperCase() !== "BODY") continue;
    let text = String(c.text ?? "");
    const n = countPlaceholders(text);
    for (let i = 0; i < n; i++) {
      text = text.replace(/\{\{[^}]+\}\}/, params[i] ?? EMPTY_PARAM);
    }
    return text.trim().slice(0, 4090);
  }

  const fallback = params.filter((p) => p !== EMPTY_PARAM).join(" · ");
  return fallback.slice(0, 4090);
}

async function fetchWabaIdFromPhoneNumberId(phoneNumberId: string, accessToken: string): Promise<string | null> {
  const fields = encodeURIComponent("whatsapp_business_account{id}");
  const url = `${META_API_BASE}/${encodeURIComponent(phoneNumberId)}?fields=${fields}`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${accessToken}` } });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  const wabaObj = json.whatsapp_business_account as { id?: string } | undefined;
  const waba = wabaObj?.id != null ? String(wabaObj.id).trim() : "";
  return waba || null;
}

async function resolveWabaId(
  admin: SupabaseClient,
  organizationId: string,
  whatsappAccountId: string,
  phoneNumberId: string,
  accessToken: string,
): Promise<string | null> {
  const { data: acc } = await admin
    .from("organization_whatsapp_accounts")
    .select("whatsapp_business_account_id")
    .eq("id", whatsappAccountId)
    .eq("organization_id", organizationId)
    .maybeSingle();

  let wabaId = String(acc?.whatsapp_business_account_id ?? "").trim();
  if (!wabaId) {
    const { data: meta } = await admin
      .from("organization_meta_config")
      .select("whatsapp_business_account_id")
      .eq("organization_id", organizationId)
      .maybeSingle();
    wabaId = String(meta?.whatsapp_business_account_id ?? "").trim();
  }
  if (!wabaId && phoneNumberId) {
    wabaId = (await fetchWabaIdFromPhoneNumberId(phoneNumberId, accessToken)) ?? "";
  }
  return wabaId || null;
}

function templateLanguageCode(row: Record<string, unknown>): string {
  const lang = row.language;
  if (typeof lang === "string") return lang.trim().toLowerCase();
  if (lang && typeof lang === "object" && !Array.isArray(lang)) {
    const code = (lang as { code?: string }).code;
    if (code) return String(code).trim().toLowerCase();
  }
  return "";
}

export async function fetchMetaTemplateComponents(
  wabaId: string,
  accessToken: string,
  templateName: string,
  templateLanguage: string,
): Promise<unknown[] | null> {
  const fields = encodeURIComponent("name,language,status,components");
  const url =
    `${META_API_BASE}/${encodeURIComponent(wabaId)}/message_templates` +
    `?name=${encodeURIComponent(templateName)}&fields=${fields}&limit=20`;

  const res = await fetch(url, { headers: { Authorization: `Bearer ${accessToken}` } });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok) {
    console.error("fetchMetaTemplateComponents:", json);
    return null;
  }

  const rows = Array.isArray(json.data) ? (json.data as Record<string, unknown>[]) : [];
  const wantLang = templateLanguage.trim().toLowerCase() || "id";
  const match =
    rows.find((r) => templateLanguageCode(r) === wantLang) ??
    rows.find((r) => String(r.name ?? "").trim() === templateName.trim()) ??
    rows[0];

  const components = match?.components;
  return Array.isArray(components) ? components : null;
}

export async function buildLeadWhatsAppStoredBody(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    whatsappAccountId: string;
    phoneNumberId: string;
    accessToken: string;
    templateName: string;
    templateLanguage: string;
    bodyParams: string[];
  },
): Promise<string> {
  const wabaId = await resolveWabaId(
    admin,
    args.organizationId,
    args.whatsappAccountId,
    args.phoneNumberId,
    args.accessToken,
  );

  if (wabaId) {
    const components = await fetchMetaTemplateComponents(
      wabaId,
      args.accessToken,
      args.templateName,
      args.templateLanguage,
    );
    if (components) {
      return renderFilledTemplateBody(components, args.bodyParams);
    }
  }

  const filled = renderFilledTemplateBody(null, args.bodyParams);
  if (filled.trim()) return filled.slice(0, 4090);
  return `[Template: ${args.templateName.trim()}]`.slice(0, 200);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { normalizeWebId } from "./urlParams.ts";

export type OrganizationWhatsAppCredentials = {
  whatsappAccountId: string;
  phoneNumberId: string;
  accessToken: string;
};

export const WA_ACCOUNT_NOT_MAPPED_CODE = "WA_ACCOUNT_NOT_MAPPED";
export const WA_ACCOUNT_NOT_MAPPED_ERROR = "wa_account_not_mapped";

type WaAccountRow = {
  id: string;
  phone_number_id: string;
  meta_access_token: string | null;
  is_active: boolean;
};

async function resolveAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  waAccount: WaAccountRow,
): Promise<string | null> {
  let accessToken = String(waAccount.meta_access_token ?? "").trim();
  if (!accessToken) {
    const { data: orgMeta } = await admin
      .from("organization_meta_config")
      .select("meta_access_token")
      .eq("organization_id", organizationId)
      .maybeSingle();
    accessToken = String(orgMeta?.meta_access_token ?? "").trim();
  }
  return accessToken || null;
}

function credentialsFromRow(
  waAccount: WaAccountRow,
  accessToken: string,
): OrganizationWhatsAppCredentials {
  return {
    whatsappAccountId: String(waAccount.id),
    phoneNumberId: String(waAccount.phone_number_id),
    accessToken,
  };
}

export async function resolveOrganizationWhatsAppCredentials(
  admin: SupabaseClient,
  organizationId: string,
  options?: { webId?: string | null },
): Promise<
  | { ok: true; credentials: OrganizationWhatsAppCredentials }
  | { ok: false; error: string; code?: string }
> {
  const normalizedWebId = options?.webId != null ? normalizeWebId(String(options.webId)) : "";

  if (!normalizedWebId) {
    return {
      ok: false,
      error: WA_ACCOUNT_NOT_MAPPED_ERROR,
      code: WA_ACCOUNT_NOT_MAPPED_CODE,
    };
  }

  const { data: mapping, error: mapErr } = await admin
    .from("organization_whatsapp_web_id_accounts")
    .select("whatsapp_account_id, is_active")
    .eq("organization_id", organizationId)
    .eq("web_id", normalizedWebId)
    .eq("is_active", true)
    .maybeSingle();

  if (mapErr) {
    console.error("resolveOrganizationWhatsAppCredentials mapping:", mapErr);
    return { ok: false, error: mapErr.message };
  }

  if (!mapping?.whatsapp_account_id) {
    return {
      ok: false,
      error: WA_ACCOUNT_NOT_MAPPED_ERROR,
      code: WA_ACCOUNT_NOT_MAPPED_CODE,
    };
  }

  const { data: waAccount, error: accErr } = await admin
    .from("organization_whatsapp_accounts")
    .select("id, phone_number_id, meta_access_token, is_active")
    .eq("id", mapping.whatsapp_account_id)
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .maybeSingle();

  if (accErr) {
    console.error("resolveOrganizationWhatsAppCredentials account:", accErr);
    return { ok: false, error: accErr.message };
  }

  if (!waAccount?.phone_number_id) {
    return {
      ok: false,
      error: WA_ACCOUNT_NOT_MAPPED_ERROR,
      code: WA_ACCOUNT_NOT_MAPPED_CODE,
    };
  }

  const accessToken = await resolveAccessToken(admin, organizationId, waAccount);
  if (!accessToken) {
    return { ok: false, error: "Token Meta WhatsApp tidak ditemukan." };
  }

  return {
    ok: true,
    credentials: credentialsFromRow(waAccount, accessToken),
  };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { normalizeWebId } from "./urlParams.ts";

function digitsOnly(value: string): string {
  return value.replace(/\D/g, "");
}

/** Reverse lookup: Meta phone_number_id → web_id via organization_whatsapp_web_id_accounts. */
export async function resolveWebIdFromPhoneNumberId(
  admin: SupabaseClient,
  organizationId: string,
  phoneNumberId: string | null | undefined,
): Promise<string | null> {
  const pnId = String(phoneNumberId ?? "").trim();
  if (!pnId) return null;

  const { data: account, error: accErr } = await admin
    .from("organization_whatsapp_accounts")
    .select("id")
    .eq("organization_id", organizationId)
    .eq("phone_number_id", pnId)
    .eq("is_active", true)
    .maybeSingle();

  if (accErr || !account?.id) {
    if (accErr) console.warn("resolveWebIdFromPhoneNumberId account:", accErr.message);
    return null;
  }

  const { data: mapping, error: mapErr } = await admin
    .from("organization_whatsapp_web_id_accounts")
    .select("web_id")
    .eq("organization_id", organizationId)
    .eq("whatsapp_account_id", account.id)
    .eq("is_active", true)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (mapErr) {
    console.warn("resolveWebIdFromPhoneNumberId mapping:", mapErr.message);
    return null;
  }

  const webId = mapping?.web_id;
  return webId != null ? normalizeWebId(String(webId)) || null : null;
}

/** Reverse lookup via display_phone_number on organization_whatsapp_accounts. */
export async function resolveWebIdFromDisplayPhoneNumberDb(
  admin: SupabaseClient,
  organizationId: string,
  displayPhoneNumber: string | null | undefined,
): Promise<string | null> {
  const digits = digitsOnly(String(displayPhoneNumber ?? ""));
  if (!digits) return null;

  const { data: accounts, error: accErr } = await admin
    .from("organization_whatsapp_accounts")
    .select("id, phone_number_id, display_phone_number, is_active")
    .eq("organization_id", organizationId)
    .eq("is_active", true);

  if (accErr) {
    console.warn("resolveWebIdFromDisplayPhoneNumberDb accounts:", accErr.message);
    return null;
  }

  const match = (accounts ?? []).find((row) => {
    const display = digitsOnly(String(row.display_phone_number ?? ""));
    const pn = digitsOnly(String(row.phone_number_id ?? ""));
    return display === digits || pn === digits;
  });

  if (!match?.id) return null;

  const { data: mapping, error: mapErr } = await admin
    .from("organization_whatsapp_web_id_accounts")
    .select("web_id")
    .eq("organization_id", organizationId)
    .eq("whatsapp_account_id", match.id)
    .eq("is_active", true)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (mapErr) {
    console.warn("resolveWebIdFromDisplayPhoneNumberDb mapping:", mapErr.message);
    return null;
  }

  const webId = mapping?.web_id;
  return webId != null ? normalizeWebId(String(webId)) || null : null;
}

/** Prefer phone_number_id; fall back to display number. */
export async function resolveWebIdForInboundWhatsApp(args: {
  admin: SupabaseClient;
  organizationId: string;
  phoneNumberId?: string | null;
  displayPhoneNumber?: string | null;
}): Promise<string | null> {
  const fromPn = await resolveWebIdFromPhoneNumberId(
    args.admin,
    args.organizationId,
    args.phoneNumberId,
  );
  if (fromPn) return fromPn;

  return resolveWebIdFromDisplayPhoneNumberDb(
    args.admin,
    args.organizationId,
    args.displayPhoneNumber,
  );
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { isOmnichannelApiTokenExpired } from "./auth.ts";
import { normalizeWebId } from "./urlParams.ts";

type ManageJson = (body: unknown, status?: number) => Response;

function normalizeWebIdArg(value: unknown): string {
  return normalizeWebId(String(value ?? ""));
}

export async function handleWebIdWhatsAppAccountAction(
  admin: SupabaseClient,
  body: Record<string, unknown>,
  organizationId: string,
  json: ManageJson,
): Promise<Response | null> {
  const action = String(body.action ?? "").trim();

  if (action === "listWebIdWhatsAppAccounts") {
    const { data, error } = await admin
      .from("organization_whatsapp_web_id_accounts")
      .select(
        "id, web_id, whatsapp_account_id, is_active, updated_at, organization_whatsapp_accounts(id, whatsapp_business_name, display_phone_number, phone_number_id, is_active)",
      )
      .eq("organization_id", organizationId)
      .order("web_id", { ascending: true });

    if (error) return json({ success: false, error: error.message }, 500);

    const { data: tokens } = await admin
      .from("organization_omnichannel_api_tokens")
      .select("web_id, is_active, expires_at")
      .eq("organization_id", organizationId);

    const candidateWebIds = new Set<string>();
    for (const row of tokens ?? []) {
      if (!row.is_active) continue;
      if (isOmnichannelApiTokenExpired(row.expires_at as string | null)) continue;
      const wid = normalizeWebIdArg(row.web_id);
      if (wid) candidateWebIds.add(wid);
    }

    return json({
      success: true,
      mappings: data ?? [],
      candidate_web_ids: [...candidateWebIds].sort(),
    });
  }

  if (action === "getWebIdWhatsAppAccount") {
    const webId = normalizeWebIdArg(body.web_id);
    if (!webId) return json({ success: false, error: "web_id wajib." }, 400);

    const { data, error } = await admin
      .from("organization_whatsapp_web_id_accounts")
      .select(
        "id, web_id, whatsapp_account_id, is_active, updated_at, organization_whatsapp_accounts(id, whatsapp_business_name, display_phone_number, phone_number_id, is_active)",
      )
      .eq("organization_id", organizationId)
      .eq("web_id", webId)
      .eq("is_active", true)
      .maybeSingle();

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, mapping: data ?? null });
  }

  if (action === "upsertWebIdWhatsAppAccount") {
    const webId = normalizeWebIdArg(body.web_id);
    const whatsappAccountId = String(body.whatsapp_account_id ?? "").trim();

    if (!webId || !whatsappAccountId) {
      return json({ success: false, error: "web_id dan whatsapp_account_id wajib." }, 400);
    }

    const { data: account, error: accErr } = await admin
      .from("organization_whatsapp_accounts")
      .select("id, is_active")
      .eq("id", whatsappAccountId)
      .eq("organization_id", organizationId)
      .maybeSingle();

    if (accErr) return json({ success: false, error: accErr.message }, 500);
    if (!account?.id || !account.is_active) {
      return json({ success: false, error: "Akun WhatsApp tidak ditemukan atau tidak aktif." }, 422);
    }

    const now = new Date().toISOString();
    const patch = {
      organization_id: organizationId,
      web_id: webId,
      whatsapp_account_id: whatsappAccountId,
      is_active: true,
      updated_at: now,
    };

    const { data, error } = await admin
      .from("organization_whatsapp_web_id_accounts")
      .upsert(patch, { onConflict: "organization_id,web_id" })
      .select(
        "id, web_id, whatsapp_account_id, is_active, updated_at, organization_whatsapp_accounts(id, whatsapp_business_name, display_phone_number, phone_number_id, is_active)",
      )
      .single();

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true, mapping: data });
  }

  if (action === "deleteWebIdWhatsAppAccount") {
    const webId = normalizeWebIdArg(body.web_id);
    if (!webId) return json({ success: false, error: "web_id wajib." }, 400);

    const { error } = await admin
      .from("organization_whatsapp_web_id_accounts")
      .update({ is_active: false, updated_at: new Date().toISOString() })
      .eq("organization_id", organizationId)
      .eq("web_id", webId);

    if (error) return json({ success: false, error: error.message }, 500);
    return json({ success: true });
  }

  return null;
}

export const RESERVED_LEAD_BODY_KEYS = new Set([
  "name",
  "phone_number",
  "email",
  "notes",
  "session_id",
  "status",
]);

export const MAX_FORM_DATA_KEYS = 64;
export const MAX_FORM_DATA_BYTES = 32 * 1024;

const FORM_DATA_KEY_PATTERN = /^[a-zA-Z][a-zA-Z0-9_]{0,63}$/;

export type LeadFormCoreFields = {
  name: string;
  phone_number: string;
  email: string;
  notes: string | null;
  session_id: string | null;
  status: string | null;
};

export type ExtractLeadFormResult =
  | { ok: true; core: LeadFormCoreFields; formData: Record<string, unknown> | null }
  | { ok: false; error: string };

function isPrimitiveFormValue(value: unknown): boolean {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

function validateFormDataValue(value: unknown, path: string): string | null {
  if (isPrimitiveFormValue(value)) return null;

  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      const err = validateFormDataValue(value[i], `${path}[${i}]`);
      if (err) return err;
    }
    return null;
  }

  if (value !== null && typeof value === "object") {
    return `${path}: nested object tidak diperbolehkan.`;
  }

  return `${path}: tipe nilai tidak didukung.`;
}

export function validateFormDataRecord(formData: Record<string, unknown>): string | null {
  const keys = Object.keys(formData);
  if (keys.length > MAX_FORM_DATA_KEYS) {
    return `Maksimal ${MAX_FORM_DATA_KEYS} field tambahan per submission.`;
  }

  for (const key of keys) {
    if (!FORM_DATA_KEY_PATTERN.test(key)) {
      return `Nama field "${key}" tidak valid. Gunakan huruf, angka, dan underscore (maks. 64 karakter).`;
    }
    const err = validateFormDataValue(formData[key], key);
    if (err) return err;
  }

  const serialized = JSON.stringify(formData);
  if (serialized.length > MAX_FORM_DATA_BYTES) {
    return `form_data melebihi batas ${MAX_FORM_DATA_BYTES} byte.`;
  }

  return null;
}

export function extractLeadFormPayload(body: Record<string, unknown>): ExtractLeadFormResult {
  const core: LeadFormCoreFields = {
    name: String(body.name ?? "").trim(),
    phone_number: body.phone_number != null ? String(body.phone_number).trim() : "",
    email: body.email != null ? String(body.email).trim() : "",
    notes: body.notes != null ? String(body.notes).trim() || null : null,
    session_id: body.session_id != null ? String(body.session_id).trim() || null : null,
    status: body.status != null ? String(body.status).trim() || null : null,
  };

  const formData: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body)) {
    if (RESERVED_LEAD_BODY_KEYS.has(key)) continue;
    if (value === undefined) continue;
    formData[key] = value;
  }

  const keys = Object.keys(formData);
  if (keys.length === 0) {
    return { ok: true, core, formData: null };
  }

  const validationError = validateFormDataRecord(formData);
  if (validationError) {
    return { ok: false, error: validationError };
  }

  return { ok: true, core, formData };
}
